import {temperatureUnitSymbol} from './temperature-units.js?v=411156r1';
import {installWeatherLegendOverlay} from './legend-overlay.js?v=411149r1';
import {temperatureColor,temperatureText,temperatureLegendRange} from './temperature-data.js?v=411157r1';
class ThermalLegend{}installWeatherLegendOverlay(ThermalLegend,{});
export function createTemperatureLegend(owner,kind){
 const view=new ThermalLegend(),s=owner._weatherTemperatureState(),prefix='weather-'+kind+'-legend-',ensure=view._weatherLegendEnsureUi,sync=view._weatherLegendSyncUi;
 view.shadow={getElementById:id=>owner.shadow?.getElementById(id.startsWith('weather-legend-')?id.replace('weather-legend-',prefix):id),append:node=>{if(node.id==='weather-legend-style')node.id=prefix+'style';owner.shadow.append(node);}};
 const narrow=(owner._map?.getSize().x||800)<720;
 view.__weatherLegendState={models:new Map(),resizeHandler:null,resizeObserver:null,collapsed:false,anchor:null,ui:{view:s.config.legendUi?.[kind]?.view==='classes'?'classes':'bar',rain:s.config.legendUi?.[kind]?.rain===true,snow:false},position:s.config.legendPositions[kind]||{x:kind==='temperature'||narrow?0:1,y:narrow&&kind==='advection'?.48:.98},mounted:false};
 view._weatherLegendMode=()=>s.config.visible&&s.config[kind==='temperature'?'temperatureLegend':'advectionLegend']&&(kind==='temperature'||s.config.advection)?'auto':'off';
 view._weatherLegendSavePosition=position=>{s.config.legendPositions[kind]=position;owner._weatherTemperatureSave();};view._weatherLegendSaveUi=ui=>{s.config.legendUi??={};s.config.legendUi[kind]={...ui};owner._weatherTemperatureSave();};
 view._weatherDisplaySetLegendMode=()=>owner._weatherTemperatureSet({[kind==='temperature'?'temperatureLegend':'advectionLegend']:false});
 view._weatherLegendEnsureUi=function(){const host=ensure.call(this);if(host){host.id=prefix+'overlay';host.setAttribute('aria-label',kind==='temperature'?'Temperaturlegende':'Advektionslegende');}return host;};
 // The shared overlay supplies premium frame, drag, bounds, close and chevron behavior.
 // Its precipitation-family renderer stays untouched; thermal content uses its own view.
 view._weatherLegendSyncUi=function(){const host=this._weatherLegendEnsureUi();if(!host)return;host.hidden=!this._weatherLegendVisibleModels().length;if(host.hidden)return;host.style.zIndex='711';host.querySelector('[data-weather-legend-heading]').textContent=kind==='temperature'?'Temperatur · 2 m':'Thermische Advektion · 850 hPa';host.querySelector('.weather-legend-view-picker').hidden=false;host.querySelectorAll('[data-weather-legend-view]').forEach(button=>{const active=button.dataset.weatherLegendView===this._weatherLegendState().ui.view;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
  const collapsed=this._weatherLegendState().ui.rain,section=document.createElement('section');section.className='weather-legend-section release-history-future';section.classList.toggle('collapsed',collapsed);section.toggleAttribute('open',!collapsed);
  const head=document.createElement('div');head.className='weather-legend-section-head';const label=document.createElement('strong');label.textContent=kind==='temperature'?'Temperatur':'Thermischer Transport';const toggle=document.createElement('button');toggle.type='button';toggle.className='weather-legend-toggle';toggle.dataset.weatherSectionToggle='rain';toggle.setAttribute('aria-label',label.textContent+' ein- oder ausklappen');toggle.setAttribute('aria-expanded',String(!collapsed));const chevron=document.createElement('span');chevron.className='release-history-future-chevron';chevron.setAttribute('aria-hidden','true');toggle.append(chevron);head.append(label,toggle);
  const body=document.createElement('div');body.className='weather-legend-section-body';body.inert=collapsed;const inner=document.createElement('div');inner.className='weather-legend-section-inner';inner.append(this._weatherLegendRenderVisual());body.append(inner);section.append(head,body);host.querySelector('[data-weather-legend-list]').replaceChildren(section);requestAnimationFrame(()=>this._weatherLegendPosition());};
 view._weatherLegendRenderVisual=()=>{
  const box=document.createElement('div');box.style.cssText='width:100%;font:11px/1.4 system-ui;overflow-wrap:anywhere;color:#dce3ec';const classes=view._weatherLegendState().ui.view==='classes';const p=text=>{const n=document.createElement('p');n.style.margin='5px 0';n.textContent=text;box.append(n);};const c=s.config,f=s.field;
  if(kind==='temperature'){
   const [min,max]=temperatureLegendRange(f,c),bar=document.createElement('div');bar.setAttribute('role','img');bar.setAttribute('aria-label',owner._t('temperature.unit.label')+' · '+owner._t('temperature.unit.'+c.unit));bar.style.cssText='height:14px;border-radius:4px;margin:6px 0;background:linear-gradient(90deg,'+Array.from({length:25},(_,i)=>temperatureColor(273.15+min+(max-min)*i/24,c)+' '+i/24*100+'%').join(',')+')';box.append(bar);
   if(classes){const chips=document.createElement('div');chips.className='gr-thermal-classes';for(let i=0;i<6;i++){const v=min+(max-min)*i/5;const chip=document.createElement('span');chip.style.borderTop='5px solid '+temperatureColor(273.15+v,c);chip.textContent=temperatureText(273.15+v,c.unit,true,owner._locale());chips.append(chip);}box.append(chips);bar.hidden=true;}
   const ticks=document.createElement('div');ticks.style.cssText='display:flex;justify-content:space-between;gap:5px;flex-wrap:wrap';for(const v of [min,(min+max)/2,max]){const t=document.createElement('span');t.textContent=temperatureText(v+273.15,c.unit,true,owner._locale());ticks.append(t);}box.append(ticks);ticks.hidden=classes;
   p('Violett ausschließlich für extreme Hitze ab '+temperatureText(c.stops[8]+273.15,c.unit,true,owner._locale())+'. Darstellungsgrenzen sind keine Warnschwellen.');p('2-m-Modelltemperatur, keine Stationsmessung. Beschriftungen sind native Gitterwerte; deren Dichte erhöht die Datenauflösung nicht.');
  }else{
   if(c.flowForm!=='classic')p(owner._t('flow.'+(c.flowForm==='curved_arrows'?'arrowsHelp':'linesHelp')));p(owner._t('flow.advectionHelp'));
   const row=document.createElement('div');row.style.cssText='height:14px;border-radius:4px;background:linear-gradient(90deg,#247aff,#6edbff,#e8edf1,#ffab50,#fa413b,#e9449a)';box.append(row);const scale=document.createElement('div');scale.className='gr-advection-scale';const limits=[-6,-3,0,3,6];for(const value of limits){const span=document.createElement('span');span.textContent=(value>0?'+':'')+value+' K/h';scale.append(span);}box.append(scale);if(classes){row.hidden=true;scale.classList.add('classes');}p('Blau: Kaltlufttransport · neutral: geringe Advektion · Orange/Rot: Warmlufttransport. Einheit K/h.');p('−v · ∇T auf gemeinsamer 850-hPa-Ebene. Pfeile folgen dem dortigen Wind; ihre Farbe beschreibt den horizontalen Temperaturtransport.');p('Keine unmittelbare lokale Temperaturänderung und kein 2-m-Temperaturtrend. Abweichung vom separat dargestellten 10-m-Wind ist möglich. Bereiche unter Modellboden, NoData und ungültige Gradienten bleiben ausgespart.');p('Die Bewegung ist visuell skaliert. '+(c.paused?'Animation pausiert.':'Tempo '+c.tempo+' · Dichte '+c.density+'.'));if(f?.advection.status!=='ready')p('Nicht verfügbar: '+(f?.advection.unavailable?.code||s.error||'Keine kohärenten Felder.'));
  }
  if(f){p(f.provenance.attribution);p('Modelllauf UTC: '+f.model_run+' · Gültig UTC: '+f.valid_at);p('WR-Freigabe bis UTC: '+f.valid_until+' · natives GFS-Gitter '+f.native_resolution_degrees+'°, übertragen '+(f.grid.longitudes[1]-f.grid.longitudes[0]).toFixed(2)+'° × '+(f.grid.latitudes[1]-f.grid.latitudes[0]).toFixed(2)+'°.');}else p(s.status);
  return box;
 };return view;
}
export function updateTemperatureLegends(owner){const s=owner._weatherTemperatureState();for(const kind of ['temperature','advection']){if(!s.legends[kind]&&s.config.visible&&s.config[kind==='temperature'?'temperatureLegend':'advectionLegend'])s.legends[kind]=createTemperatureLegend(owner,kind);s.legends[kind]?._weatherLegendSetModel(kind,{family:'temperature',capability:kind==='temperature'?'weather.temperature.field_2m':'weather.temperature.advection_850hpa',title:kind==='temperature'?'Temperatur · 2 m':'Advektion · 850 hPa',unit:kind==='temperature'?temperatureUnitSymbol(s.config.unit):'K/h',entries:[{label:kind,color:'#fff'}],active:true});}}
